// Monotonic decreasing stack: next greater element for each index
// Stores INDICES, not values
function nextGreaterElement(arr) {
  const n = arr.length;
  const result = new Array(n).fill(-1); // default: no next greater
  const stack = []; // indices, decreasing by arr[index] from bottom to top

  for (let i = 0; i < n; i++) {
    // Pop all indices whose value is smaller than current element
    while (stack.length > 0 && arr[stack[stack.length - 1]] < arr[i]) {
      const idx = stack.pop();
      result[idx] = arr[i]; // arr[i] is the next greater for idx
    }
    stack.push(i);
  }
  return result;
}

// Largest rectangle in histogram (single pass)
function largestRectangleArea(heights) {
  const stack = []; // increasing stack of indices
  let maxArea = 0;
  const n = heights.length;

  for (let i = 0; i <= n; i++) {
    const h = i === n ? 0 : heights[i]; // sentinel 0 flushes remaining stack
    while (stack.length > 0 && heights[stack[stack.length - 1]] > h) {
      const height = heights[stack.pop()];
      const left = stack.length > 0 ? stack[stack.length - 1] : -1;
      const width = i - left - 1;
      maxArea = Math.max(maxArea, height * width);
    }
    stack.push(i);
  }
  return maxArea;
}
